}

# Find each chapter practice question section and insert exam box before it
$pattern = '(<div class="net-exam-questions">)\s*<h4>[^<]*Chapter (\d+) .* Practice Questions</h4>'
$matches = [regex]::Matches($html, $pattern)
Write-Host "Found $($matches.Count) chapter practice sections"

# Process in reverse to preserve positions
$injections = @()
foreach ($m in $matches) {
    $chNum = $m.Groups[2].Value
    $position = $m.Groups[1].Index  # position of <div class="net-exam-questions">
    if ($examBoxes.ContainsKey($chNum)) {
        $injections += @{ pos = $position; html = $examBoxes[$chNum] }
        Write-Host "  Ch $chNum : scheduled"
    } else {
        Write-Host "  Ch $chNum : NO exam box defined! Skipping."
    }
}

Write-Host "Will inject $($injections.Count) exam-prep boxes"

# Apply in reverse order
$sorted = $injections | Sort-Object -Property pos -Descending
$cnt = 0
foreach ($inj in $sorted) {
    $html = $html.Substring(0, $inj.pos) + $inj.html + $html.Substring($inj.pos)
    $cnt++
}

Write-Host "Writing..."
[System.IO.File]::WriteAllText($f, $html, [System.Text.UTF8Encoding]::new($false))
$newKB = [math]::Round((Get-Item $f).Length/1KB,0)
Write-Host "Size: $origKB -> $newKB KB (+$($newKB-$origKB)KB)"
Write-Host "Added $cnt exam-prep boxes"
